var a=`1091-fish-amok`;var n=`world-1091`;var t=`KH`;var s=`southeast-asia`;var r=4;var o=58;var l={en:`Fish Amok`,ua:`Рибний амок`};var m={en:`Fish Amok is a dish from Cambodia prepared with thai red curry paste, lemongrass, galangal, shrimp paste. This is a home-scale version with measured ingredients in the individual steps where they are used. Home fish amok uses available Thai curry paste; Khmer kroeung differs in aromatics and texture.`,ua:`Рибний амок, страва кухні країни Камбоджа, яку готують із таких продуктів: червона тайська паста карі, лемонграс, галангал, креветкова паста. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Домашній рибний амок із доступною тайською пастою карі; кхмерський кроенг має інший аромат і текстуру.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`thai-red-curry-paste`,60,`g`],[`lemongrass`,30,`g`],[`galangal`,25,`g`],[`shrimp-paste`,15,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`tilapia`,650,`g`],[`coconut-milk`,450,`ml`],[`chicken-egg`,2,`pcs`],[`fish-sauce`,35,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[[`banana-leaf`,7,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 27 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 27 хвилин до готовності.`,t:[`steaming`],m:27,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var g={slug:a,id:n,country:`KH`,region:s,servings:4,minutes:58,title:l,text:m,steps:d};export{t as country,g as default,n as id,o as minutes,s as region,r as servings,a as slug,d as steps,m as text,l as title};